_units'] }}</strong></div></div><div class="panel data-table"><table><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Units</th><th>Merchandise</th><th>Discount</th><th>Fulfillment</th></tr></thead><tbody>@forelse($salesLines as $line)<tr><td>{{ $line->order->number }}</td><td><a class="text-link" href="/marketplace/operations?{{ http_build_query(['tab'=>'orders','customer'=>$line->order->customer['email'] ?? '','from'=>$from->toDateString(),'to'=>$to->toDateString()]) }}">{{ $line->order->customer['email'] ?? '' }} →</a></td><td>{{ $line->title }}</td><td>{{ $line->quantity }} ({{ $line->refunded_quantity }} refunded)</td><td>${{ number_format($line->unit_price_cents*$line->quantity/100,2) }}</td><td>${{ number_format($line->discount_cents/100,2) }}</td><td>{{ $line->fulfillment_status }}</td></tr>@empty<tr><td colspan="7">No verified live sales match these dates.</td></tr>@endforelse</tbody></table></div></section><section id="products"><h2>Products and allocated stock.</h2><div class="product-grid">@foreach($listings as $listing)<article class="panel">@if($listing->images)<img src="{{ $listing->images[0] }}" alt="" class="market-cover">@endif<h3>{{ $listing->title }}</h3><p>${{ number_format($listing->price_cents/100,2) }} · {{ $listing->status }}<br>{{ $listing->stock_quantity }} units available</p><a class="text-link" href="/marketplace/operations?tab=listings">Manage listing →</a></article>@endforeach</div></section><section id="markets" class="subsection"><h2>Markets and shows.</h2>@forelse($markets as $market)<div class="panel"><h3>{{ $market->name }}</h3><p>{{ $market->starts_at->setTimezone($market->timezone)->format('M j, Y · g:i a') }} · {{ $market->makers->first()?->pivot->status }}<br>Booth {{ $market->makers->first()?->pivot->booth ?: 'not assigned' }}</p><a class="text-link" href="/marketplace/operations?tab=markets">Manage participation →</a></div>@empty<p>No markets or shows assigned yet.</p>@endforelse</section><section id="payments" 